import pyAether as pyScript

def resolve_lpp(design, layer, purpose):
    lr = pyScript.emyGetLayerNumByName(design, pyScript.emyString(layer))
    pr = pyScript.emyGetPurposeNumByName(design, pyScript.emyString(purpose))
    return (lr[1], pr[1])

import pyAether as pyScript

def style_name(enum_val):
    style = pyScript.emyEndStyle(enum_val)
    s = pyScript.emyString(str(style.getName()))
    return str(s)
